import datetime
import time

# Symbolic constants to replace magic numbers/strings
DURATION_FORMAT = "%H:%M:%S"
DATE_FORMAT = "%Y-%m-%d"
DATETIME_FORMAT = "%Y-%m-%d %H:%M:%S"
SECONDS_PER_MINUTE = 60

class TimeUtils:

    def __init__(self):
        self._datetime = datetime.datetime.now()

    @property
    def datetime(self):
        return self._datetime

    @datetime.setter
    def datetime(self, value):
        self._datetime = value

    def get_current_time(self):
        return self.format_datetime(self._datetime, DURATION_FORMAT)

    def get_current_date(self):
        return self.format_datetime(self._datetime, DATE_FORMAT)

    def add_seconds(self, seconds):
        new_datetime = self._datetime + datetime.timedelta(seconds=seconds)
        return self.format_datetime(new_datetime, DURATION_FORMAT)

    def string_to_datetime(self, string):
        return datetime.datetime.strptime(string, DATETIME_FORMAT)

    def datetime_to_string(self, dt):
        return self.format_datetime(dt, DATETIME_FORMAT)

    def get_minutes(self, string_time1, string_time2):
        time1 = self.string_to_datetime(string_time1)
        time2 = self.string_to_datetime(string_time2)
        return self.calculate_minutes_between(time1, time2)

    def get_format_time(self, year, month, day, hour, minute, second):
        time_item = datetime.datetime(year, month, day, hour, minute, second)
        return self.format_datetime(time_item, DATETIME_FORMAT)

    def format_datetime(self, dt, format_str):
        return dt.strftime(format_str)

    def calculate_minutes_between(self, time1, time2):
        total_seconds = (time2 - time1).total_seconds()
        return round(total_seconds / SECONDS_PER_MINUTE)
